import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { signup } from '../hooks/useAuth';
import { validateEmail, validateName, validatePassword } from '../utils/validation.js';

const Signup = () => {
    const navigate = useNavigate();
    const [role, setRole] = useState('');
    const [name, setName] = useState('');
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');

    const handleSignup = async (e) => {
        e.preventDefault();
        const data = { userName: name, email, password, role }

       const validation = vali

        const response = await signup(data);
        if (response.success) {
            alert(`${role},${name} ${response.message}`);
            console.log(response.user);
            navigate('/login');
        } else {
            alert( response.message);
        }
    };

    return (
        <div className="container">
            <form className="form" onSubmit={handleSignup} >
                <h1>Signup</h1>

                <select value={role} onChange={(e) => setRole(e.target.value)}>
                    <option value=""> Select Role  </option>
                    <option value="user"> User </option>
                    <option value="admin">  Admin</option>
                </select>

                <input type="text" placeholder="Name" value={name} onChange={(e) => setName(e.target.value)} />
                <input type="email" placeholder="Email" value={email} onChange={(e) => setEmail(e.target.value)} />
                <input type="password" placeholder="Password" value={password} onChange={(e) => setPassword(e.target.value)} />

                <button type="submit"> Signup </button>
                <p onClick={() => navigate('/login')}> Already have account? </p>

            </form>
        </div>
    );
};

export default Signup;
